//! Normalize the existing SDK drivers without entering their request timers.
use serde_json::Value;use std::{fs,path::Path,process::{Command,Stdio}};
fn main(){let a:Vec<_>=std::env::args_os().collect();assert_eq!(a.len(),5);let engine=std::env::var("ZOPRO_READY_ENGINE").unwrap();let dir=Path::new(&a[4]);fs::create_dir_all(dir).unwrap();let mut child=if engine=="aeglos"{let stem=Path::new(&a[1]).file_stem().unwrap().to_str().unwrap();let mut c=Command::new("/usr/local/bin/aeglos-ablation");c.args(["aeglos",&format!("/gnark-keys/{stem}.key")]).args([&a[2],&a[3]]);c.env("ZOPRO_BENCH_PROOFS",dir.parent().unwrap()).env("AEGLOS_BENCH_DISABLE_SHIFTED","0").env("AEGLOS_CPU_THREADS",std::env::var("RAYON_NUM_THREADS").unwrap()).env("GOMAXPROCS",std::env::var("RAYON_NUM_THREADS").unwrap());for(from,to)in[("ZOPRO_BENCH_PERF_CTL","CROSS_PERF_CTL"),("ZOPRO_BENCH_PERF_ACK","CROSS_PERF_ACK")]{if let Some(v)=std::env::var_os(from){c.env(to,v);}}c}else{assert!(matches!(engine.as_str(),"accepted"|"off"|"on"));let mut c=Command::new(if engine=="accepted"{"/usr/local/bin/ready-accepted"}else{"/usr/local/bin/ready-diagnostic"});c.args(&a[1..]);if engine=="on"{c.env("ZOPRO_READY_OUTPUT",dir.join("readiness.json"));}else{c.env_remove("ZOPRO_READY_OUTPUT");}c};
 child.stdout(Stdio::from(fs::File::create(dir.join("driver.stdout")).unwrap())).stderr(Stdio::from(fs::File::create(dir.join("driver.stderr")).unwrap()));let status=child.status().unwrap();assert!(status.success(),"SDK child failed: {status}");let output=fs::read_to_string(dir.join("driver.stdout")).unwrap();let mut samples=0;let mut summaries=0;
 for line in output.lines(){if let Some(s)=line.strip_prefix("SAMPLE "){let mut v:Value=serde_json::from_str(s).unwrap();if engine=="aeglos"{assert_eq!(v["cache_hit"],true);v["ms"]=v["verified_ms"].clone();}println!("SAMPLE {v}");samples+=1;}else if let Some(s)=line.strip_prefix("SUMMARY "){let mut v:Value=serde_json::from_str(s).unwrap();v["workers"]=std::env::var("RAYON_NUM_THREADS").unwrap().parse::<u64>().unwrap().into();println!("SUMMARY {v}");summaries+=1;}}
 assert_eq!(samples,a[3].to_str().unwrap().parse::<usize>().unwrap());assert_eq!(summaries,1);
}
